#include <iostream>
#include <vector>
#include <queue>
using namespace std;

void bfsTraversal(int startNode, int numVertices, const vector<vector<int>>& adjMatrix) {
    vector<int> visitied(numVertices, 0);
    visitied[startNode] = 1;
    queue<int> q;
    q.push(startNode);
    vector<int> bfsOrder;

    while (!q.empty()) {
        int node = q.front();
        q.pop();
        bfsOrder.push_back(node);
        for (int i = 0; i < numVertices; i++) {
            if (adjMatrix[node][i] == 1 && !visitied[i]) {
                visitied[i] = 1;
                q.push(i);
            }
        }
    }

    for (auto i : bfsOrder) {
        cout << i;
    }
}

int main() {
    // Number of vertices
    int V = 5; 
    /* We are creating a simple connected graph:
          0 --- 1
          |   / |
          |  /  |
          | /   |
          2 --- 3 --- 4
    */
    // Initialize an Adjacency Matrix with all 0s
    vector<vector<int>> adjMatrix(V, vector<int>(V, 0));
    // Adding edges (Undirected Graph)
    adjMatrix[0][1] = 1; adjMatrix[1][0] = 1;
    adjMatrix[0][2] = 1; adjMatrix[2][0] = 1;
    adjMatrix[1][2] = 1; adjMatrix[2][1] = 1;
    adjMatrix[1][3] = 1; adjMatrix[3][1] = 1;
    adjMatrix[2][3] = 1; adjMatrix[3][2] = 1;
    adjMatrix[3][4] = 1; adjMatrix[4][3] = 1;
    // Run BFS starting from node 0
    bfsTraversal(0, V, adjMatrix);
    return 0;
}
